-- Empty-target guard, including tables whose integer IDs might not collide.
CREATE TEMP TABLE fixture_load_guard (empty_target INTEGER NOT NULL CHECK(empty_target=1));
INSERT OR ROLLBACK INTO fixture_load_guard VALUES (NOT EXISTS(SELECT 1 FROM persons) AND NOT EXISTS(SELECT 1 FROM employers) AND NOT EXISTS(SELECT 1 FROM lenders) AND NOT EXISTS(SELECT 1 FROM employments) AND NOT EXISTS(SELECT 1 FROM income_activity_forms) AND NOT EXISTS(SELECT 1 FROM income_records) AND NOT EXISTS(SELECT 1 FROM monthly_salary_declarations) AND NOT EXISTS(SELECT 1 FROM credit_products) AND NOT EXISTS(SELECT 1 FROM product_participants) AND NOT EXISTS(SELECT 1 FROM payment_history) AND NOT EXISTS(SELECT 1 FROM credit_events) AND NOT EXISTS(SELECT 1 FROM bureau_inquiries) AND NOT EXISTS(SELECT 1 FROM fico_scores) AND NOT EXISTS(SELECT 1 FROM fico_reason_codes) AND NOT EXISTS(SELECT 1 FROM insolvency_records) AND NOT EXISTS(SELECT 1 FROM card_fraud_records));
DROP TABLE fixture_load_guard;
